SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag, COUNT(DISTINCT a.subject_id) AS patient_count, AVG(e.complexity_score) AS avg_complexity_score, AVG(a.discharge_date - a.admission_date) AS avg_length_of_stay, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS death_count, SUM(CASE WHEN a.discharge_date - a.admission_date <= 30 THEN 1 ELSE 0 END) AS readmission_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 61 AND 71 AND a.admission_type = 'Hemorrhagic stroke' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.admission_type, a.admit_provider_id, a.admission_location, a.discharge_location, a.insurance, a.language, a.marital_status, a.race, a.edregtime, a.edouttime, a.hospital_expire_flag NULLS LAST;